const text = String($json.rawText || "[NON_TEXT_MESSAGE]");

// 1) حوّل الأرقام العربية (٠١٢٣) لأرقام إنجليزية
const arabicDigits = "٠١٢٣٤٥٦٧٨٩";
let t = text.replace(/[٠-٩]/g, d => arabicDigits.indexOf(d));

// 2) احمي الروابط مؤقتاً (عشان ما تنخفي) واحفظيها
const urlRegex = /(https?:\/\/[^\s]+|www\.[^\s]+)/gi;
const links = t.match(urlRegex) || [];
let i = 0;
t = t.replace(urlRegex, () => `__LINK${i++}__`);

// 3) اخفي البيانات الحساسة
t = t.replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, "[EMAIL]");     // إيميلات
t = t.replace(/\b(?:\d[ -]?){13,19}\b/g, "[CARD]");        // أرقام بطاقات
t = t.replace(/\+?\d[\d\s-]{6,}\d/g, "[PHONE]");           // أرقام هواتف
t = t.replace(/\b\d{4,8}\b/g, "[NUMBER]");                 // أكواد تحقق وأرقام حسابات

// 4) رجّعي الروابط مكانها
t = t.replace(/__LINK(\d+)__/g, (_, n) => links[n]);

return { json: { cleanText: t, links } };
